/**
 * Module 3190 - Time Hours Format Settings
 * 
 * This module provides utilities for managing the time hours format setting
 * in TradingView charts (12-hour vs 24-hour format).
 * 
 * @module 3190
 * @category Settings/Time
 */

import { getValue, remove, setValue, onSync } from './1765-settings-adapter.js';
import { createPrimitiveProperty } from './41072-property-utils.js';

/**
 * Setting key for time hours format
 * @private @constant
 */
const TIME_HOURS_FORMAT_SETTING_KEY = 'time_hours_format';

/**
 * Default time format value (24-hour format)
 * @private @constant
 */
const DEFAULT_TIME_FORMAT = '24-hours';

/**
 * Gets the current time hours format setting value
 * Falls back to 24-hour format if not set
 * 
 * @private
 * @returns {string} Current time format ('24-hours' or '12-hours')
 */
function getCurrentTimeFormat() {
  return getValue(TIME_HOURS_FORMAT_SETTING_KEY, DEFAULT_TIME_FORMAT);
}

/**
 * Time hours format property
 * 
 * A reactive property that manages the time format setting.
 * Automatically syncs with persistent storage.
 * 
 * @type {Property<string>}
 * @public
 * 
 * @example
 * // Get current value
 * const format = timeHoursFormatProperty.value();
 * 
 * // Set new value
 * timeHoursFormatProperty.setValue('12-hours');
 */
export const timeHoursFormatProperty = createPrimitiveProperty(getCurrentTimeFormat());

/**
 * Restores time hours format settings to default value (24-hours)
 * 
 * This function:
 * 1. Resets the property value to '24-hours'
 * 2. Removes the persisted setting from storage
 * 
 * @public
 * 
 * @example
 * // Reset to default 24-hour format
 * restoreTimeHoursFormatSettingsValue();
 */
export function restoreTimeHoursFormatSettingsValue() {
  timeHoursFormatProperty.setValue(DEFAULT_TIME_FORMAT);
  remove(TIME_HOURS_FORMAT_SETTING_KEY);
}

// Auto-sync: Subscribe to settings changes
// When settings sync occurs, update property from storage
onSync.subscribe(null, () => {
  timeHoursFormatProperty.setValue(getCurrentTimeFormat());
});

// Auto-save: Subscribe to property changes
// When property changes, persist to storage
timeHoursFormatProperty.subscribe(null, () => {
  setValue(TIME_HOURS_FORMAT_SETTING_KEY, timeHoursFormatProperty.value());
});

/**
 * Available time format constants
 * @enum {string}
 * @public
 */
export const TimeFormat = {
  /** 24-hour format (e.g., 14:30) */
  HOURS_24: '24-hours',
  /** 12-hour format (e.g., 2:30 PM) */
  HOURS_12: '12-hours'
};

/**
 * Default exports
 */
export default {
  timeHoursFormatProperty,
  restoreTimeHoursFormatSettingsValue,
  TimeFormat
};


  // Module 3343
/**
 * Module 3343 - Keyboard Modifiers and Event Utilities
 * 
 * This module provides utilities for handling keyboard modifiers (Ctrl, Alt, Shift, Meta)
 * and keyboard events in a cross-platform manner (Windows/Mac/Linux).
 * 
 * Features:
 * - Modifier key detection and hashing
 * - Human-readable modifier strings
 * - Platform-specific keyboard shortcuts (Mac vs Windows)
 * - Key code to string conversion
 * 
 * @module 3343
 * @category Input/Keyboard
 */

import { isMac, isIOS } from './75774-platform-detection.js';

/**
 * Modifier bit flags
 * Each modifier has a unique bit position for bitwise operations
 * 
 * @enum {number}
 * @public
 */
export const Modifiers = {
  /** No modifiers pressed */
  None: 0,
  /** Alt key (Option on Mac) */
  Alt: 512,
  /** Shift key */
  Shift: 1024,
  /** Control key (Cmd on Mac) */
  Mod: isMac || isIOS ? 2048 : 256,
  /** Control key */
  Control: 256,
  /** Meta key (Command on Mac, Windows key on Windows) */
  Meta: 2048
};

/**
 * Checks if the current platform uses Mac-style keyboard
 * @returns {boolean} True if Mac or iOS
 */
export const isMacKeyboard = isMac || isIOS;

/**
 * Extracts modifier flags from a keyboard event
 * 
 * @param {KeyboardEvent} event - The keyboard event
 * @returns {number} Bitwise combination of modifier flags
 * 
 * @example
 * const modifiers = modifiersFromEvent(keyboardEvent);
 * if (modifiers & Modifiers.Shift) {
 *   console.log('Shift is pressed');
 * }
 */
export function modifiersFromEvent(event) {
  let modifiers = 0;
  
  if (event.shiftKey) {
    modifiers += Modifiers.Shift;
  }
  if (event.altKey) {
    modifiers += Modifiers.Alt;
  }
  if (event.ctrlKey) {
    modifiers += Modifiers.Control;
  }
  if (event.metaKey) {
    modifiers += Modifiers.Meta;
  }
  
  return modifiers;
}

/**
 * Creates a hash from a keyboard event including modifiers and key code
 * 
 * @param {KeyboardEvent} event - The keyboard event
 * @returns {number} Unique hash combining modifiers and key code
 */
export function hashFromEvent(event) {
  return modifiersFromEvent(event) | event.keyCode;
}

/**
 * Converts modifier flags to human-readable string
 * 
 * Platform-aware: Shows Mac symbols (⌘, ⌥, ⇧) on Mac, 
 * Windows names (Ctrl, Alt, Shift) on other platforms.
 * 
 * @param {number} modifiers - Bitwise modifier flags
 * @param {boolean} [withSpaces=true] - Include spaces between modifier names
 * @returns {string} Human-readable modifier string
 * 
 * @example
 * // On Mac: "⌘⇧"
 * // On Windows: "Ctrl + Shift"
 * humanReadableModifiers(Modifiers.Mod | Modifiers.Shift);
 */
export function humanReadableModifiers(modifiers, withSpaces = true) {
  let result = '';
  
  if (modifiers & Modifiers.Control) {
    result += formatModifier(isMac ? '^' : 'Ctrl', withSpaces);
  }
  if (modifiers & Modifiers.Alt) {
    result += formatModifier(isMac ? '⌥' : 'Alt', withSpaces);
  }
  if (modifiers & Modifiers.Shift) {
    result += formatModifier(isMac ? '⇧' : 'Shift', withSpaces);
  }
  if (modifiers & Modifiers.Meta) {
    result += formatModifier(isMac ? '⌘' : 'Win', withSpaces);
  }
  
  return result;
}

/**
 * Converts a keyboard event to human-readable shortcut string
 * 
 * @param {KeyboardEvent} event - The keyboard event
 * @returns {string} Human-readable shortcut (e.g., "Ctrl+S", "⌘C")
 * 
 * @example
 * // Returns: "Ctrl + S" or "⌘ S"
 * humanReadableHash(keyboardEvent);
 */
export function humanReadableHash(event) {
  let result = humanReadableModifiers(event);
  const keyCode = 255 & event.keyCode;
  
  // Special key mappings
  const specialKeys = isMacKeyboard ? MAC_SPECIAL_KEYS : WIN_SPECIAL_KEYS;
  
  if (keyCode in specialKeys) {
    result += specialKeys[keyCode];
  } else {
    // Convert to character
    result += String.fromCharCode(keyCode);
  }
  
  return result;
}

/**
 * Maps special key codes to readable names (Mac version)
 * @private
 */
const MAC_SPECIAL_KEYS = {
  9: '⇥',      // Tab
  13: '↵',     // Enter
  27: 'Esc',   // Escape
  8: '⌫',      // Backspace
  32: 'Space',
  35: 'End',
  36: 'Home',
  37: '←',     // Left arrow
  38: '↑',     // Up arrow
  39: '→',     // Right arrow
  40: '↓',     // Down arrow
  45: 'Ins',   // Insert
  46: 'Del',   // Delete
  188: ',',
  191: '/'
};

/**
 * Maps special key codes to readable names (Windows version)
 * @private
 */
const WIN_SPECIAL_KEYS = {
  9: 'Tab',
  13: 'Enter',
  27: 'Esc',
  8: 'Backspace',
  32: 'Space',
  35: 'End',
  36: 'Home',
  37: 'ArrowLeft',
  38: 'ArrowUp',
  39: 'ArrowRight',
  40: 'ArrowDown',
  45: 'Ins',
  46: 'Del',
  188: ',',
  191: '/'
};

// Add F1-F16 function keys to both mappings
for (let i = 1; i <= 16; i++) {
  const keyCode = i + 111;
  MAC_SPECIAL_KEYS[keyCode] = `F${i}`;
  WIN_SPECIAL_KEYS[keyCode] = `F${i}`;
}

/**
 * Formats a modifier name with appropriate spacing
 * @private
 * @param {string} name - Modifier name
 * @param {boolean} withSpaces - Whether to include spaces
 * @returns {string} Formatted modifier string
 */
function formatModifier(name, withSpaces) {
  if (withSpaces) {
    return isMacKeyboard ? `${name} ` : `${name} + `;
  }
  return name;
}

/**
 * Default exports
 */
export default {
  Modifiers,
  isMacKeyboard,
  modifiersFromEvent,
  hashFromEvent,
  humanReadableModifiers,
  humanReadableHash
};


  // Module 3354
/**
 * Module 3354 - Chart Layout Management
 * 
 * This module provides utilities for managing chart layouts in TradingView.
 * It handles single and multi-chart layouts, layout expressions, and sizing operations.
 * 
 * Features:
 * - Layout type detection (single vs multiple)
 * - Layout validation
 * - Layout size calculations
 * - Layout expression parsing
 * 
 * @module 3354
 * @category Layout/Management
 */

import './26743-layout-extensions.js';
import './62548-layout-presets.js';

/**
 * Internal layout registry
 * Stores custom layout configurations
 * @private
 */
let layoutRegistry = {};

/**
 * Built-in single chart layout
 * The default layout showing one chart
 * 
 * @type {LayoutDefinition}
 * @constant
 */
const SINGLE_LAYOUT = {
  /** Display title */
  title: '1 chart',
  /** Number of charts in layout */
  count: 1,
  /** Layout type identifier */
  layoutType: 's',
  
  /**
   * Calculates size for a sublayout
   * @param {number} totalSize - Total available size
   * @param {number} index - Sublayout index
   * @returns {number} Size for the sublayout
   * @throws {RangeError} If index is invalid for single layout
   */
  sizer: (totalSize, index) => {
    if (index !== 0) {
      throw new RangeError('invalid index');
    }
    return totalSize;
  },
  
  /**
   * Returns layout splitters configuration
   * @returns {Array} Empty array for single layout
   */
  splitters: () => [],
  
  /**
   * Applies resize operation
   * @param {Object} params - Resize parameters
   * @returns {Object} Resize result
   */
  resizeApplier: (params) => params.output,
  
  /**
   * Synchronizes sublayouts by splitter
   * @param {Object} splitter - Splitter configuration
   * @returns {Object} Synced sublayout
   */
  syncSublayoutsBySplitter: (splitter) => splitter,
  
  /** Layout expression tree */
  expression: ['h', 0]
};

/**
 * All available layouts
 * Combines built-in and custom layouts
 * 
 * @type {Object<string, LayoutDefinition>}
 * @public
 */
export const layouts = {
  ...SINGLE_LAYOUT,
  ...layoutRegistry
};

/**
 * Checks if a layout code represents a single chart layout
 * 
 * @param {string} layoutCode - The layout code to check
 * @returns {boolean} True if single chart layout
 * @private
 */
function isSingleLayout(layoutCode) {
  return layoutCode === 's';
}

/**
 * Checks if a layout code represents a multiple chart layout
 * 
 * @param {string} layoutCode - The layout code to check
 * @returns {boolean} True if multiple chart layout
 * @public
 * 
 * @example
 * if (isMultipleLayout(currentLayout)) {
 *   showLayoutSplitOptions();
 * }
 */
export function isMultipleLayout(layoutCode) {
  return !isSingleLayout(layoutCode);
}

/**
 * Validates if a layout code is supported
 * 
 * @param {string} layoutCode - The layout code to validate
 * @returns {boolean} True if layout is supported
 * @public
 * 
 * @example
 * if (!isSupportedLayout(userLayout)) {
 *   fallbackToDefaultLayout();
 * }
 */
export function isSupportedLayout(layoutCode) {
  return isSingleLayout(layoutCode) || layoutRegistry.hasOwnProperty(layoutCode);
}

/**
 * Attempts to guess the most suitable layout for given context
 * Currently defaults to single chart layout
 * 
 * @param {any} context - Layout context (currently unused)
 * @returns {string} Layout code ('s' for single)
 * @public
 * 
 * @example
 * const suggestedLayout = tryGuessingTheMostSuitableLayout(chartContext);
 * applyLayout(suggestedLayout);
 */
export function tryGuessingTheMostSuitableLayout(context) {
  return 's';
}

/**
 * Layout definition structure
 * @typedef {Object} LayoutDefinition
 * @property {string} title - Human-readable title
 * @property {number} count - Number of charts
 * @property {string} layoutType - Layout type identifier
 * @property {Function} sizer - Size calculation function
 * @property {Function} splitters - Splitters configuration getter
 * @property {Function} resizeApplier - Resize operation applier
 * @property {Function} syncSublayoutsBySplitter - Sublayout synchronizer
 * @property {Array} expression - Layout expression tree
 */

/**
 * Default exports
 */
export default {
  layouts,
  isMultipleLayout,
  isSupportedLayout,
  tryGuessingTheMostSuitableLayout
};


